$content = Get-Content "backend/src/main/kotlin/com/attendance/server/services/AttendanceService.kt" -Raw
$content = $content -replace "(?s)val session = AttendanceSessions\.selectAll\(\)`n\s+\.where \{ \(AttendanceSessions\.classId eq cid\) and \(AttendanceSessions\.sessionStatus eq `"ACTIVE`"\) \}`n\s+\.firstOrNull\(\)`n\s+\?: return@map SyncRecordResponse\(record\.id, `"NOT_FOUND`", 0, 0, 0\)", "val session = AttendanceSessions.selectAll()`n                        .where { AttendanceSessions.classId eq cid }`n                        .orderBy(AttendanceSessions.startedAt to org.jetbrains.exposed.sql.SortOrder.DESC)`n                        .firstOrNull()`n                        ?: return@map SyncRecordResponse(record.id, `"NOT_FOUND`", 0, 0, 0)"
Set-Content "backend/src/main/kotlin/com/attendance/server/services/AttendanceService.kt" $content
